-- Schema of database 'hh_healthcamp' (PostgreSQL 16), generated by Hibernate from the JPA entities.
-- Reference only: the services create/update these tables automatically (spring.jpa.hibernate.ddl-auto=update).

CREATE TABLE public.camp_beneficiaries (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    age integer,
    camp_id bigint NOT NULL,
    camp_name character varying(255),
    gender character varying(10),
    name character varying(255) NOT NULL,
    phone character varying(255),
    registered_on date,
    resident_id bigint,
    services_received character varying(500),
    village character varying(255),
    CONSTRAINT camp_beneficiaries_gender_check CHECK (((gender)::text = ANY ((ARRAY['MALE'::character varying, 'FEMALE'::character varying, 'OTHER'::character varying])::text[])))
);
ALTER TABLE public.camp_beneficiaries ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.camp_beneficiaries_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.camp_follow_ups (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    action character varying(500) NOT NULL,
    assigned_to character varying(255),
    beneficiary_id bigint NOT NULL,
    beneficiary_name character varying(255),
    camp_id bigint,
    camp_name character varying(255),
    completed_date date,
    due_date date NOT NULL,
    outcome_notes character varying(500),
    priority character varying(10),
    screening_id bigint,
    status character varying(15),
    village character varying(255),
    CONSTRAINT camp_follow_ups_priority_check CHECK (((priority)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT camp_follow_ups_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'MISSED'::character varying])::text[])))
);
ALTER TABLE public.camp_follow_ups ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.camp_follow_ups_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.camp_screenings (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    beneficiary_id bigint NOT NULL,
    beneficiary_name character varying(255),
    camp_id bigint,
    camp_name character varying(255),
    notes character varying(500),
    outcome character varying(10) NOT NULL,
    referred boolean,
    referred_to character varying(255),
    result_value character varying(255),
    screened_by character varying(255),
    screening_date date,
    screening_type character varying(20) NOT NULL,
    CONSTRAINT camp_screenings_outcome_check CHECK (((outcome)::text = ANY ((ARRAY['NORMAL'::character varying, 'ABNORMAL'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT camp_screenings_screening_type_check CHECK (((screening_type)::text = ANY ((ARRAY['BLOOD_PRESSURE'::character varying, 'BLOOD_SUGAR'::character varying, 'BMI'::character varying, 'HAEMOGLOBIN'::character varying, 'VISION'::character varying, 'DENTAL'::character varying, 'TB_SYMPTOMS'::character varying, 'ORAL_CANCER'::character varying, 'BREAST_EXAM'::character varying, 'CHILD_GROWTH'::character varying, 'MALARIA'::character varying])::text[])))
);
ALTER TABLE public.camp_screenings ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.camp_screenings_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
