CREATE TABLE public.health_camps (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    budget double precision,
    camp_code character varying(20),
    camp_type character varying(25) NOT NULL,
    description character varying(1000),
    end_date date,
    health_centre_id bigint,
    health_centre_name character varying(255),
    name character varying(255) NOT NULL,
    organizer character varying(255),
    outcome_summary character varying(1000),
    start_date date NOT NULL,
    status character varying(15),
    target_beneficiaries integer,
    venue character varying(255),
    village character varying(255) NOT NULL,
    CONSTRAINT health_camps_camp_type_check CHECK (((camp_type)::text = ANY ((ARRAY['GENERAL_CHECKUP'::character varying, 'EYE_CARE'::character varying, 'DENTAL'::character varying, 'MATERNAL_CHILD_HEALTH'::character varying, 'VACCINATION'::character varying, 'NCD_SCREENING'::character varying, 'TB_SCREENING'::character varying, 'BLOOD_DONATION'::character varying, 'AWARENESS'::character varying, 'MENTAL_HEALTH'::character varying])::text[]))),
    CONSTRAINT health_camps_status_check CHECK (((status)::text = ANY ((ARRAY['PLANNED'::character varying, 'ONGOING'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying])::text[])))
);
ALTER TABLE public.health_camps ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.health_camps_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
